   "summaryFull": "这场戏相当于什么\n\n**相当于主角的「当场被宣判」：他以为自己在逃一次抓捕，结果被告知真正锁住孩子的，是他自己当年写下的规则。**\n\n前半场是追逃。他在出口和孩子之间选了孩子（L27–31）。后半场是审判。身份（L52）、罪名（L90、L102）和罪证（L160–166）依次落下。最后一刀不是挨打，而是「It's following the protocol you wrote」（L148）。观众看完的落点不是「被抓了」，而是「他认出了自己」。L153「刚才急着找出口的眼神，停了下来」，这一句就是这场的结果。\n\n收尾的倒影像父子（L188–190），但两人「还没有迈出第一步」（L194）。观众带着「关系成立了，罪感也压下来了」的感觉进黑场。\n\n---",
