    "actor": "凯恩飞行器",
    "visibleAction": "凯恩的飞行器转入离场航道。 引擎声迅速逼近。 暗色机腹从镜头近处横掠而过，逐渐遮住下方的废料区，最终占满画面。 完全遮挡的瞬间，切入黑场。 引擎声远去。 雨声和城市底盘深处的低鸣仍然持续。",
