   "g1": {
    "inside": "【戏核】看向前方出口——再往前几步就能转入钢架后遮蔽。朝那个方向迈出半步，又停住。计时器提示音变急促。身体仍朝出口，脸却转回诺亚。远处红光已沿废料堆边缘铺开（将入组二，此处只作边缘预告）。咬紧牙，折返。",
    "outside": "半步＝整场道德选择的可见动作；红光边缘＝制度已到门口。",
    "drama": "定案A的轴心——先让观众相信他差点逃掉，再看他回头；折返不是英雄姿态，是咬牙。",
    "intent": "出口／诺亚分占景深；半步停须演清楚。"
   },
