   "performance": {
    "raw": "组长看终端，朝旁边几堆废料偏头：「You two, check over there…」两名持枪者转向继续搜。组长按耳机走近：「We've got this one. Two tagged parts.」无人机光束移到诺亚；旧型号识别停在未完成结果——须可读：**N-08A-H — REVIEW PENDING**。伊把诺亚挡到身后，一只手压紧包口；目光仍在出口／组长／电磁棍／头顶无人机间停不下来。引擎声从雨幕上方压近。",
    "goal": null,
    "action": null,
    "eyeline": null
   },
   "actionEn": "The team leader checks his terminal and tilts his head toward nearby piles; two riflemen turn away to search. He presses his earpiece and walks toward Elias. The drone beam moves onto Noah; an old model ID reads as unfinished (blank glowing panel; text in post). Elias shields Noah behind him, one hand pressing the bag shut, eyes darting: exit, team leader, baton, drone. An engine roar presses down from above the rain.",
