   "performance": {
    "raw": "伊张口，先喘一下，急着解释。说话时目光越过凯恩肩侧，落向那条仍然看得见的出口。凯恩的目光跟着一辆驶过的运输机械移开；伊说完，等着他看过来。",
    "goal": null,
    "action": null,
    "eyeline": null
   },
   "actionEn": "Elias opens his mouth, takes a breath first, rushing to explain. While speaking his eyes slide past Kane's shoulder to the still-visible exit. Kane's gaze drifts after a passing transport machine. Elias finishes and waits for him to look back.",
   "dialogue": [
    {
     "ref": "D13",
     "en": "It was all thrown out. I only took what was still good.",
     "zh": "都是扔掉的东西。我就捡了点还能用的。",
     "speaker": "伊莱亚斯",
     "type": "对白",
     "t0": 0.4,
     "t1": 5.0,
     "timing": "估算"
    }
   ],
