   "performance": {
    "raw": "**第二记**落在肩背。伊侧身踉跄，鞋底在湿滑金属边缘打滑；左肩撞水坑旁低矮废料，整个人跌进近处黑水。工具包翻倒在身边——**散落链须一件件清楚**：VISTA 模块、胶带、包着半支医疗凝胶的布团滚出；儿童机械手从敞开包口滑出一截，露出掌部与腕节，其余仍压在包内。",
    "goal": null,
    "action": null,
    "eyeline": null
   },
   "actionEn": "The second strike lands on his shoulder and back. Elias stumbles sideways, sole slipping on a wet metal edge; his LEFT shoulder hits low scrap beside the puddle and he falls into the black water. The tool bag overturns beside him; spill chain readable one by one: a module, tape, a cloth bundle wrapping half a medical gel tube; a child-size mechanical hand slides partly out of the open bag, palm and wrist joint showing, the rest still inside.",
