   "performance": {
    "raw": "**戏核后半**——诺亚立刻向他伸出一只手，刚要迈步，身体却骤然停住；那一步没有落下，膝部伺服发出一声短促绷紧。胸前提示亮起——须可读：**CARE UNIT RESTRICTION: CORPORATE ENFORCEMENT INTERVENTION PROHIBITED.** 它低头看一眼提示，又看向伊。高处，凯恩目光仍随运输机械移向远处。",
    "goal": null,
    "action": null,
    "eyeline": null
   },
   "actionEn": "Noah immediately reaches out one hand and starts to step, then freezes; the step never lands; a short taut servo sound from the knee. A restriction panel lights on its chest (blank glowing panel; text added in post). Noah looks down at it, then at Elias. High above, Kane's eyes still follow a transport machine into the distance.",
