   "performance": {
    "raw": "凯恩注意落在诺亚停住的膝关节和胸前限制提示上：「It's following the protocol you wrote, Mr. Elias.」说到最后称呼时，才短暂看向水里的伊。伊撑地动作停住；望着诺亚的目光慢慢移开，转向眼前凯恩，再看向组长和那根垂下来的电磁棍。刚才急着找出口的眼神，停了下来。（可略借 B：撑地手松劲。）",
    "goal": null,
    "action": null,
    "eyeline": null
   },
   "actionEn": "Kane's attention lands on Noah's frozen knee joint and chest panel. Only on the final form of address does he glance briefly down at Elias in the water. Elias's push on the ground stops; his eyes leave Noah, move to Kane, then to the team leader and the lowered baton. The searching-for-the-exit look stops.",
   "dialogue": [
    {
     "ref": "D20",
     "en": "It's following the protocol you wrote, Mr. Elias.",
     "zh": "它正在执行你写下的协议，伊莱亚斯先生。",
     "speaker": "凯恩",
     "type": "对白",
     "t0": 0.4,
     "t1": 3.6,
     "timing": "估算"
    }
   ],
