   "performance": {
    "raw": "诺亚声音再次响起，比第一次快一点。伊没有再回头。看着凯恩，嘴唇微微分开，却没有说出什么；撑在地上的手还在，只是已经不再使劲。",
    "goal": null,
    "action": null,
    "eyeline": null
   },
   "actionEn": "Noah's voice a second time, slightly faster than the first. Elias does not look back. He watches Kane, lips slightly parted, saying nothing; his hand is still on the ground but no longer pushing.",
