   "performance": {
    "raw": "凯恩俯身拾起 VISTA 模块，看一眼标识，递向身侧；组长立即接住：「Yes, Commander Mercer.」——比他对队员说话时更规整；收妥后继续核对另一件。另一名回收者蹲下，扣住包口露出的腕节，将那截儿童机械前臂抽出来收走。伊看着——**没有再抓**。远处大范围扫描光渐退；留在他们上方的无人机仍悬停；诺亚胸前限制提示没有消失。凯恩扫过诺亚胸前型号编号，转身走向平台：「It was never yours, Mr. Elias.」——最后称呼传来时，他已背对伊，走回飞行器。",
    "goal": null,
    "action": null,
    "eyeline": null
   },
   "actionEn": "Kane bends, picks up the module, glances at its marking and holds it out sideways; the team leader takes it at once and stows it, then checks the next item. Another reclaimer crouches, grips the exposed wrist joint and pulls the child-size mechanical forearm out of the bag, taking it. Elias watches and keeps his hands still. The wide-area scan light recedes; the drone above still hovers; Noah's chest panel stays lit. Kane looks over Noah's chest model number, turns and walks back to the aircraft, already with his back to Elias on his last line.",
   "dialogue": [
    {
     "ref": "D22",
     "en": "Yes, Commander Mercer.",
     "zh": "是，默瑟指挥官。",
     "speaker": "组长",
     "type": "对白",
     "t0": 0.4,
     "t1": 1.8,
     "timing": "估算"
    },
    {
     "ref": "D23",
     "en": "It was never yours, Mr. Elias.",
     "zh": "它本来就不属于你，伊莱亚斯先生。",
     "speaker": "凯恩",
     "type": "对白",
     "t0": 2.1,
     "t1": 4.5,
     "timing": "估算"
    }
   ],
