   "performance": {
    "raw": "组长收起终端，抬眼看仍撑在水里的伊，又看一眼停在原地的诺亚：「All right. Let them go.」回收者解除限制；诺亚胸前提示熄灭——它立刻走向伊。组长侧身让出它经过的位置，随后带着收缴物离开。",
    "goal": null,
    "action": null,
    "eyeline": null
   },
   "actionEn": "The team leader puts away the terminal, looks at Elias still in the water, then at Noah frozen in place. The reclaimers release the restriction; Noah's chest panel goes dark and it immediately walks to Elias. The team leader steps aside to let it pass, then leaves with the seized items.",
