   "performance": {
    "raw": "撤离的回收者从散落物品旁经过，一只靴子踩上浸湿的布团——一声很轻的脆响。半支医疗凝胶外壳裂开；残余凝胶挤进黑水，很快被持续落下的雨冲散。靴子没有停。",
    "goal": null,
    "action": null,
    "eyeline": null
   },
   "actionEn": "A departing reclaimer passes the scattered items; one boot steps on the soaked cloth bundle. A very soft crack. The half medical gel tube's shell splits; remaining gel squeezes into the black water and is washed away by the rain. The boot does not stop.",
