   "performance": {
    "raw": "**关系停拍**——水坑里两道被雨点打碎的倒影靠在一起，慢慢直起；矮小那一道仰着头，扶住高的那一道——像一个孩子，扶着自己的父亲。镜头从倒影缓缓抬起，带出两人全身。伊的手搭在诺亚肩上；已站稳，却仍低着头；雨水沿衣摆落下。诺亚等着他。两人还没有迈出第一步。",
    "goal": null,
    "action": null,
    "eyeline": null
   },
   "actionEn": "In the puddle, two rain-broken reflections lean together and slowly straighten; the smaller one looks up, supporting the taller one, like a child holding up its father. The camera rises slowly from the reflection to reveal both full bodies. Elias's hand rests on Noah's shoulder; he is standing but still head down; rain falls from his coat hem. Noah waits for him. Neither has taken the first step.",
