   "performance": {
    "raw": "镜头向后拉开，逐渐升高，同时缓缓摇向更广阔废料区。高处通路在他们身后展开：先前离开的两名回收者继续往不同堆料区走；组长带着收缴物走向回收车；持电磁棍者转入另一条作业通道；机械犬穿过碎铁与断裂构架，追随新探测信号而去。**低处，两个人仍站在原地。**（借 C 的系统交叉，但两人未迈步须始终可读。）",
    "goal": null,
    "action": null,
    "eyeline": null
   },
   "actionEn": "The camera pulls back, rises and slowly pans toward the wider scrapyard. High walkways open behind them: two reclaimers continue toward different piles; the team leader carries the seized items to a recovery vehicle; the baton reclaimer turns into another work lane; the robot dog crosses broken frames following a new signal. Low in frame, the two still stand in place.",
