   "performance": {
    "raw": "继续升高，视野展宽。巨大废料滑槽垂在城市底盘下方；机械臂抓起残骸、转向、松开；施工机器人沿堆料边缘切割搬运；运输机械载着分拣废件穿过轨道。远处又一批废料倾落，闷响滚过雨幕。空中扫描无人机已散开，红色光点沿各自路线远去；更远处装载飞行器从厂区上方缓慢驶过。平台上，凯恩飞行器闭合舱门，升离地面。伊和诺亚的身影在不断展开的废料区中缩小；交错管道、轨道和仍在工作的机械渐渐占满画面。——拉开给够尺度，**不抢** 030 关系停拍。",
    "goal": null,
    "action": null,
    "eyeline": null
   },
   "actionEn": "The camera keeps rising, the view widening: a huge scrap chute hangs beneath the city underbelly; robotic arms grab, turn, release; construction robots cut and haul along pile edges; transport machines carry sorted scrap along rails. Far away another load of scrap pours down with a dull boom. Scan drones disperse, red dots receding along their routes. On the platform Kane's aircraft closes its hatch and lifts off. Elias and Noah shrink in the expanding scrapyard.",
